#include "labels.hpp"

std::vector<std::string> labelIds(const std::vector<std::string>& ids) {
    std::vector<std::string> labels;
    labels.reserve(ids.size());
    for (std::size_t i = 0; i < ids.size(); ++i) {
        labels[i] = "item-" + ids[i];
    }
    return labels;
}
